<?php $__env->startPush('scripts'); ?>
    <script src="<?php echo e(asset('assets/extensions/simple-datatables/umd/simple-datatables.js')); ?>"></script>
    <script src="<?php echo e(asset('assets/static/js/pages/simple-datatables.js')); ?>"></script>
    <script>
        // let dataTable = new simpleDatatables.DataTable("#table1");


        const showBtns = document.querySelectorAll('.btn-show');
        const modalShowContent = document.getElementById('modalContent');

        showBtns.forEach(btn => {
            btn.addEventListener('click', () => {
                const id = btn.dataset.id;

                modalShowContent.innerHTML = `
            <div class="modal-body text-center">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        `;

                fetch(`/purchase-orders/${id}`)
                    .then(response => response.text())
                    .then(html => {
                        modalShowContent.innerHTML = html;
                    })
                    .catch(error => {
                        modalShowContent.innerHTML = `
                    <div class="modal-body text-danger text-center">
                        Gagal memuat data
                    </div>
                `;
                        console.error(error);
                    });
            });
        });

        const editBtn = document.querySelectorAll('.btn-edit');
        const editModalContent = document.getElementById('editModalContent');

        editBtn.forEach(btn => {
            btn.addEventListener('click',()=>{
                const id = btn.dataset.id;

                editModalContent.innerHTML = `
                <div class="modal-body text-center">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
                `;

                fetch(`/purchase-orders/${id}/edit`)
                    .then(response => response.text())
                    .then(html => {
                        editModalContent.innerHTML = html;
                    })
                    .catch(error => {
                        editModalContent.innerHTML = `
                    <div class="modal-body text-danger text-center">
                        Gagal memuat data
                    </div>
                `;
                    })
            });
        });
    </script>
